import torch


def _to_dtype(d):
    if isinstance(d, torch.dtype):
        return d
    return getattr(torch, str(d).replace("torch.", ""))


def gen_inputs(ctx, device):
    inp_shape = list(ctx["inp__shape"])
    inp_dtype = _to_dtype(ctx["inp__dtype"])
    src_shape = list(ctx["src__shape"])
    src_dtype = _to_dtype(ctx["src__dtype"])
    index_len = int(list(ctx["index__shape"])[0])
    inp = torch.randn(inp_shape, dtype=inp_dtype, device=device)
    index = torch.randperm(index_len, device=device)
    src = torch.randn(src_shape, dtype=src_dtype, device=device)
    return {"inp": inp, "index": index, "src": src}


def run(inp, dim, index, src):
    return torch.index_copy(inp, dim, index, src)
